import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { PrCi, PrStatus } from '../types'

const prs = atom({ plugin: 'pr-status-band', key: 'prs' } as const, {})
const isHidden = atom({ plugin: 'pr-status-band', key: 'isHidden' } as const, false)

const SERVER = 'github'
const POLL_MS = 120_000
const KEEP_CLOSED_MS = 10 * 60_000
const FAILED = new Set(['failure', 'cancelled', 'timed_out', 'action_required', 'startup_failure'])
const NOTIFIED_PR = /"pr":"([\w.-]+)\/([\w.-]+)#(\d+)"/g
const PR_URL = /github\.com\/([\w.-]+)\/([\w.-]+)\/pull\/(\d+)/

type Ref = { owner: string; repo: string; number: number }

const keyOf = (r: Ref) => `${r.owner}/${r.repo}#${r.number}`

const refFrom = (m: RegExpMatchArray | null): Ref | undefined =>
  m?.[1] && m[2] && m[3] ? { owner: m[1], repo: m[2], number: Number(m[3]) } : undefined

export const summarizeChecks = (runs: { status?: string; conclusion?: string | null }[]): PrCi => {
  if (runs.length === 0) return 'none'
  if (runs.some(r => r.status !== 'completed')) return 'running'
  if (runs.some(r => FAILED.has(String(r.conclusion)))) return 'failing'
  return 'passing'
}

/** Approvals that still count: each reviewer's latest decisive review, on the current head. */
export const countApprovals = (
  reviews: { state?: string; commit_id?: string; user?: { login?: string } }[],
  head: string,
): number => {
  const latest = new Map<string, string>()
  for (const r of reviews) {
    const login = r.user?.login
    if (!login || r.commit_id !== head) continue
    if (r.state === 'APPROVED' || r.state === 'CHANGES_REQUESTED' || r.state === 'DISMISSED') {
      latest.set(login, r.state)
    }
  }
  return [...latest.values()].filter(s => s === 'APPROVED').length
}

const inFlight = new Map<string, Promise<void>>()

async function readJson($: EngineInterface, args: Record<string, unknown>) {
  const res = await $.mcp.call(SERVER, 'pull_request_read', args)
  const text = res.content.find(b => b.type === 'text')?.text
  if (res.isError || text === undefined) throw new Error(text ?? 'empty GitHub response')
  return JSON.parse(text)
}

async function load($: EngineInterface, ref: Ref) {
  const base = { owner: ref.owner, repo: ref.repo, pullNumber: ref.number }
  const pr = await readJson($, { ...base, method: 'get' })
  const head: string = pr.head?.sha ?? ''
  const state: PrStatus['state'] = pr.merged ? 'merged' : pr.state === 'closed' ? 'closed' : 'open'
  let ci: PrCi = 'unknown'
  let approvals = 0
  if (state === 'open') {
    const checks = await readJson($, { ...base, method: 'get_check_runs' })
    ci = summarizeChecks(checks.check_runs ?? [])
    approvals = countApprovals(await readJson($, { ...base, method: 'get_reviews' }), head)
  }
  const status: PrStatus = {
    key: keyOf(ref),
    owner: ref.owner,
    repo: ref.repo,
    number: ref.number,
    title: String(pr.title ?? ''),
    head: head.slice(0, 7),
    state,
    isDraft: pr.draft === true,
    ci,
    approvals,
    checkedAt: await $.clock.now(),
  }
  await update($, prs, all => ({ ...all, [status.key]: status }))
}

/** One refresh per PR at a time; a second caller waits for the running one. */
function refresh($: EngineInterface, ref: Ref): Promise<void> {
  const key = keyOf(ref)
  const running = inFlight.get(key)
  if (running) return running
  const run = load($, ref)
    .catch(() => {
      // A failed read leaves the last known status; the next poll retries.
    })
    .finally(() => inFlight.delete(key))
  inFlight.set(key, run)
  return run
}

/** Lists the PR at once (status unknown), then fills it in without holding up the caller. */
async function track($: EngineInterface, ref: Ref) {
  const key = keyOf(ref)
  const all = await read($, prs)
  if (all[key] === undefined) {
    const placeholder: PrStatus = {
      key,
      owner: ref.owner,
      repo: ref.repo,
      number: ref.number,
      title: '',
      head: '',
      state: 'open',
      isDraft: false,
      ci: 'unknown',
      approvals: 0,
      checkedAt: await $.clock.now(),
    }
    await update($, prs, cur => ({ ...cur, [key]: cur[key] ?? placeholder }))
  }
  void refresh($, ref)
}

async function refreshOpen($: EngineInterface) {
  const now = await $.clock.now()
  const all = await read($, prs)
  const stale = Object.values(all).filter(p => p.state !== 'open' && now - p.checkedAt > KEEP_CLOSED_MS)
  if (stale.length > 0) {
    await update($, prs, cur => {
      const next = { ...cur }
      for (const p of stale) delete next[p.key]
      return next
    })
  }
  for (const p of Object.values(all)) if (p.state === 'open') await refresh($, p)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    $.clock.every(POLL_MS, () => void refreshOpen($))
    await $.command.register({
      name: 'prs',
      description: 'Shows or hides the PR status band and refreshes it.',
    })
    return next(e)
  })

  on('command.run', { command: 'prs' }, async $ => {
    const hidden = !(await read($, isHidden))
    await update($, isHidden, () => hidden)
    if (!hidden) void refreshOpen($)
    return { text: hidden ? 'PR status band hidden.' : 'PR status band shown and refreshing.' }
  })

  on('tool.call', async ($, e, next) => {
    const result = await next(e)
    const tool = String(e.tool)
    if (result.deny !== undefined) return result
    const args = e as unknown as Record<string, unknown>

    if (tool.startsWith('mcp__github__')) {
      const owner = args.owner
      const repo = args.repo
      const number = Number(args.pullNumber)
      if (typeof owner === 'string' && typeof repo === 'string' && Number.isInteger(number) && number > 0) {
        await track($, { owner, repo, number })
      } else if (tool === 'mcp__github__create_pull_request' && typeof result.text === 'string') {
        const ref = refFrom(PR_URL.exec(result.text))
        if (ref) await track($, ref)
      }
    } else if (tool === 'ReadNotifications' && typeof result.text === 'string') {
      for (const m of result.text.matchAll(NOTIFIED_PR)) {
        const ref = refFrom(m)
        if (ref) await track($, ref)
      }
    }
    return result
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, isHidden))) return next(e)
    const list = Object.values(await read($, prs)).sort((a, b) => a.number - b.number)
    if (list.length === 0) return next(e)

    const { Box, Button, Text } = $.ui.resolve(e)
    const ciColor = (ci: PrCi) =>
      ci === 'passing' ? 'green' : ci === 'failing' ? 'red' : ci === 'running' ? 'yellow' : undefined

    return (
      <Box flexDirection="column">
        {list.map(p => (
          <Box key={`row-${p.key}`} flexDirection="row" gap={1}>
            <Text bold>{`#${p.number}`}</Text>
            {p.state === 'open' ? (
              <Text color={ciColor(p.ci)}>{`CI ${p.ci}`}</Text>
            ) : (
              <Text color={p.state === 'merged' ? 'magenta' : 'red'}>{p.state}</Text>
            )}
            {p.state === 'open' ? (
              <Text color={p.approvals > 0 ? 'green' : 'yellow'}>
                {p.approvals === 1 ? '1 approval' : `${p.approvals} approvals`}
              </Text>
            ) : null}
            {p.state === 'open' && p.isDraft ? <Text dimColor>draft</Text> : null}
            <Text dimColor wrap="truncate-end">{`${p.head} ${p.title}`}</Text>
          </Box>
        ))}
        <Box flexDirection="row" gap={1}>
          <Button key="refresh" label="Refresh" onPress={() => refreshOpen($)} />
          <Button key="hide" label="Hide" onPress={() => update($, isHidden, () => true)} />
        </Box>
      </Box>
    )
  })
}

