export type PrCi = 'passing' | 'failing' | 'running' | 'none' | 'unknown'

export type PrStatus = {
  key: string
  owner: string
  repo: string
  number: number
  title: string
  head: string
  state: 'open' | 'merged' | 'closed'
  isDraft: boolean
  ci: PrCi
  approvals: number
  checkedAt: number
}

declare module 'claude-code' {
  interface PluginState {
    'pr-status-band': {
      prs: Record<string, PrStatus>
      isHidden: boolean
    }
  }
}
